import{_ as a,o as n,c as t,ag as r}from"./chunks/framework.CrXGS008.js";const p=JSON.parse('{"title":"Car Wash","description":"","frontmatter":{},"headers":[],"relativePath":"de/car-wash/index.md","filePath":"de/car-wash/index.md"}'),s={name:"de/car-wash/index.md"};function i(l,e,o,d,h,c){return n(),t("div",null,[...e[0]||(e[0]=[r(`<h1 id="car-wash" tabindex="-1">Car Wash <a class="header-anchor" href="#car-wash" aria-label="Permalink to &quot;Car Wash&quot;">​</a></h1><p>Reinfahren, Programm wählen, und das Fahrzeug rollt durch rotierende Bürsten, Schaum, Spülbögen und einen Dampftrockner, während alle in der Nähe dieselbe Wäsche sehen. Zu Fuß schnappen sich Spieler einen Hochdruckreiniger und entfernen den Schmutz Stufe für Stufe. Jeder Standort wird im Spiel platziert und jede Einstellung im Spiel bearbeitet.</p><h2 id="funktionen" tabindex="-1">Funktionen <a class="header-anchor" href="#funktionen" aria-label="Permalink to &quot;Funktionen&quot;">​</a></h2><ul><li><strong>Waschstraßen zum Durchfahren</strong>: Bürsten passend zur Fahrzeugbreite, Schaum- und Spülbögen, Dampftrockner, synchronisiert für jeden Spieler in der Nähe. Siehe <a href="/de/car-wash/tunnels">Tunnel</a>.</li><li><strong>Waschprogramme</strong>: Name, Preis, Tempo und welche Schritte laufen (Schaum, Spülen, Trocknen, Wachs). Wachs hält das Fahrzeug so lange sauber, wie du festlegst.</li><li><strong>Hochdruckreiniger</strong> an jedem Welt-Prop, den du auflistest, oder an Stationen, die du platzierst, bezahlt pro Schmutzstufe. Siehe <a href="/de/car-wash/pressure-washers">Hochdruckreiniger</a>.</li><li><strong>Editor für Waschstraßen im Spiel</strong>: Erstelle eine Waschstraße dort, wo du stehst, oder kopiere eine Waschanlage des Basisspiels, verschiebe jedes Teil mit der Tastatur, speichere.</li><li><strong>Alles in <code>/nay</code></strong>: Preise, Programme, Job-Rabatte, Zahlungskonto, gesperrte Fahrzeugklassen, Blips mit visueller Auswahl von Symbol und Farbe. Siehe <a href="/de/car-wash/settings">Einstellungen</a>.</li><li><strong>Fair und sicher</strong>: ein Fahrzeug pro Waschstraße, Prüfung auf falsche Richtung und blockierte Spur, Zahlungen und Reservierung der Waschstraße werden auf dem Server geprüft.</li><li><strong>Job-Rabatte</strong> und ein Preisprozentsatz pro Waschstraße. Spieler zahlen bar, per Bank oder erst bar, dann per Bank.</li><li><strong>Kartenbewusst</strong>: Die statischen Bürsten der Karte werden entlang jeder Waschstraße ausgeblendet und kommen zurück, wenn die Ressource stoppt. In Strawberry ersetzen die Kartendateien ohne Bürsten die Standard-Waschanlage.</li><li><strong>HTTP-API und Webhooks</strong>: Waschverlauf und Statistiken für deine Website oder deinen Bot, eine Discord-Nachricht für jede Wäsche. Siehe <a href="/de/car-wash/api">API und Webhooks</a>.</li><li><strong>Sechs Sprachen</strong>: Englisch, Französisch, Spanisch, Portugiesisch, Polnisch, Deutsch.</li></ul><h2 id="kompatibilitat" tabindex="-1">Kompatibilität <a class="header-anchor" href="#kompatibilitat" aria-label="Permalink to &quot;Kompatibilität&quot;">​</a></h2><ul><li>Frameworks: ESX Legacy, QBCore, QBox, ox_core, automatisch erkannt.</li><li>Target (optional, für die Hochdruckreiniger): ox_target oder qb-target. Ohne Target nutzen Spieler einen Tastenhinweis.</li><li>Abhängigkeiten: oxmysql und <code>nay_lib</code> (im Kauf enthalten).</li></ul><h2 id="leistung" tabindex="-1">Leistung <a class="header-anchor" href="#leistung" aria-label="Permalink to &quot;Leistung&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Zustand</th><th>Client (resmon)</th></tr></thead><tbody><tr><td>Leerlauf</td><td>0,00 ms</td></tr><tr><td>Beim Waschen eines Fahrzeugs</td><td>etwa 0,08 ms</td></tr></tbody></table><p>Gemessen mit resmon auf Game-Build 3751.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ensure oxmysql</span></span>
<span class="line"><span>ensure nay_lib</span></span>
<span class="line"><span>ensure nay_car_wash</span></span></code></pre></div><p>Alle Schritte findest du auf der Seite <a href="/de/getting-started">Erste Schritte</a>. Gib dir danach <code>nay_car_wash.config</code> (oder <code>nay.admin</code>) und öffne <code>/nay</code>. Zwei Waschstraßen sind sofort einsatzbereit: Strawberry und Little Seoul.</p>`,12)])])}const g=a(s,[["render",i]]);export{p as __pageData,g as default};
